package q.qedet.organization.policy.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import q.qedet.auth.security.ActorContext;
import q.qedet.common.exception.BadRequestException;
import q.qedet.common.exception.NotFoundException;
import q.qedet.common.model.Permission;
import q.qedet.organization.policy.dto.PolicyDtos.*;
import q.qedet.organization.policy.entity.*;
import q.qedet.organization.policy.repository.*;
import q.qedet.organization.entity.Organization;
import q.qedet.organization.repository.OrganizationRepository;
import java.time.LocalDate;

@Service
public class PolicyService {
 private final ActorContext actor; private final OrganizationRepository organizations; private final AttendancePolicyRepository attendance; private final LeavePolicyRepository leave; private final PayrollPolicyRepository payroll;
 public PolicyService(ActorContext actor, OrganizationRepository organizations, AttendancePolicyRepository attendance, LeavePolicyRepository leave, PayrollPolicyRepository payroll){this.actor=actor;this.organizations=organizations;this.attendance=attendance;this.leave=leave;this.payroll=payroll;}
 private Organization org(){return organizations.findById(actor.organizationId()).orElseThrow(()->new NotFoundException("Organization not found"));}
 private LocalDate date(LocalDate requested){return requested==null?LocalDate.now():requested;}
 private LocalDate changeDate(LocalDate requested){LocalDate date=date(requested);if(date.isBefore(LocalDate.now()))throw new BadRequestException("Policy effective date cannot be in the past");return date;}
 @Transactional(readOnly=true) public AttendancePolicyResponse attendance(LocalDate date){actor.requirePermission(Permission.HR_POLICY_VIEW);return attendance.findFirstByOrganizationIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(actor.organizationId(),date(date)).map(this::out).orElseThrow(()->new NotFoundException("Attendance policy not found"));}
 @Transactional public AttendancePolicyResponse attendance(AttendancePolicyRequest r){actor.requirePermission(Permission.HR_POLICY_EDIT);LocalDate d=changeDate(r.effectiveFrom());var current=attendance.findFirstByOrganizationIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(actor.organizationId(),d);AttendancePolicy p=current.filter(x->x.getEffectiveFrom().equals(d)).orElseGet(()->current.map(this::copy).orElseGet(AttendancePolicy::new));if(p.getId()==null){p.setOrganization(org());p.setEffectiveFrom(d);}apply(p,r);return out(attendance.save(p));}
 @Transactional(readOnly=true) public LeavePolicyResponse leave(LocalDate date){actor.requirePermission(Permission.HR_POLICY_VIEW);return leave.findFirstByOrganizationIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(actor.organizationId(),date(date)).map(this::out).orElseThrow(()->new NotFoundException("Leave policy not found"));}
 @Transactional public LeavePolicyResponse leave(LeavePolicyRequest r){actor.requirePermission(Permission.HR_POLICY_EDIT);LocalDate d=changeDate(r.effectiveFrom());var current=leave.findFirstByOrganizationIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(actor.organizationId(),d);LeavePolicy p=current.filter(x->x.getEffectiveFrom().equals(d)).orElseGet(()->current.map(this::copy).orElseGet(LeavePolicy::new));if(p.getId()==null){p.setOrganization(org());p.setEffectiveFrom(d);}apply(p,r);return out(leave.save(p));}
 @Transactional(readOnly=true) public PayrollPolicyResponse payroll(LocalDate date){actor.requirePermission(Permission.HR_POLICY_VIEW);return payroll.findFirstByOrganizationIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(actor.organizationId(),date(date)).map(this::out).orElseThrow(()->new NotFoundException("Payroll policy not found"));}
 @Transactional public PayrollPolicyResponse payroll(PayrollPolicyRequest r){actor.requirePermission(Permission.HR_POLICY_EDIT);LocalDate d=changeDate(r.effectiveFrom());var current=payroll.findFirstByOrganizationIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(actor.organizationId(),d);PayrollPolicy p=current.filter(x->x.getEffectiveFrom().equals(d)).orElseGet(()->current.map(this::copy).orElseGet(PayrollPolicy::new));if(p.getId()==null){p.setOrganization(org());p.setEffectiveFrom(d);}apply(p,r);return out(payroll.save(p));}
 public AttendancePolicy resolveAttendancePolicy(java.util.UUID organizationId, LocalDate workDate){return attendance.findFirstByOrganizationIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(organizationId,workDate).orElse(null);}
 private AttendancePolicy copy(AttendancePolicy s){AttendancePolicy p=new AttendancePolicy();p.setOrganization(s.getOrganization());p.setEffectiveFrom(s.getEffectiveFrom());apply(p,new AttendancePolicyRequest(null,s.isEnabled(),s.isRequireCheckIn(),s.isRequireCheckOut(),s.getCheckInMethod(),s.getGracePeriodMinutes(),s.isAllowEarlyCheckIn(),s.getCheckOutMethod(),s.isAllowEarlyCheckout(),s.isEarlyCheckoutRequiresApproval(),s.isRequireAttendanceQr(),s.isRequireLocation(),s.isAllowRemoteAttendance(),s.getMissingCheckoutHandling(),s.isAllowEmployeeCorrectionRequest(),s.isCorrectionRequiresApproval(),s.isCorrectionReasonRequired()));return p;}
 private LeavePolicy copy(LeavePolicy s){LeavePolicy p=new LeavePolicy();p.setOrganization(s.getOrganization());p.setEffectiveFrom(s.getEffectiveFrom());apply(p,new LeavePolicyRequest(null,s.isEnabled(),s.isAllowEmployeeRequests(),s.isRequireApproval(),s.isReasonRequired(),s.isAttachmentRequired(),s.getMinimumNoticeDays(),s.isAllowHalfDayLeave(),s.isAllowHourlyLeave(),s.isAllowNegativeBalance(),s.isCarryOverEnabled(),s.getCarryOverMaximumDays()));return p;}
 private PayrollPolicy copy(PayrollPolicy s){PayrollPolicy p=new PayrollPolicy();p.setOrganization(s.getOrganization());p.setEffectiveFrom(s.getEffectiveFrom());apply(p,new PayrollPolicyRequest(null,s.isEnabled(),s.getPayrollFrequency(),s.getPayDateRule(),s.isPayrollApprovalRequired(),s.isOvertimeAuthorizationRequired(),s.getOvertimeCalculationMethod(),s.getWeekdayOvertimeMultiplier(),s.getWeekendOvertimeMultiplier(),s.getHolidayOvertimeMultiplier(),s.isLateDeductionEnabled(),s.isAbsenceDeductionEnabled(),s.isUnpaidLeaveDeductionEnabled(),s.getMissingAttendanceHandling(),s.getPayrollCutoffDay()));return p;}
 private void apply(AttendancePolicy p,AttendancePolicyRequest r){if(r.enabled()!=null)p.setEnabled(r.enabled());if(r.requireCheckIn()!=null)p.setRequireCheckIn(r.requireCheckIn());if(r.requireCheckOut()!=null)p.setRequireCheckOut(r.requireCheckOut());if(r.checkInMethod()!=null)p.setCheckInMethod(r.checkInMethod());if(r.gracePeriodMinutes()!=null)p.setGracePeriodMinutes(r.gracePeriodMinutes());if(r.allowEarlyCheckIn()!=null)p.setAllowEarlyCheckIn(r.allowEarlyCheckIn());if(r.checkOutMethod()!=null)p.setCheckOutMethod(r.checkOutMethod());if(r.allowEarlyCheckout()!=null)p.setAllowEarlyCheckout(r.allowEarlyCheckout());if(r.earlyCheckoutRequiresApproval()!=null)p.setEarlyCheckoutRequiresApproval(r.earlyCheckoutRequiresApproval());if(r.requireAttendanceQr()!=null)p.setRequireAttendanceQr(r.requireAttendanceQr());if(r.requireLocation()!=null)p.setRequireLocation(r.requireLocation());if(r.allowRemoteAttendance()!=null)p.setAllowRemoteAttendance(r.allowRemoteAttendance());if(r.missingCheckoutHandling()!=null)p.setMissingCheckoutHandling(r.missingCheckoutHandling());if(r.allowEmployeeCorrectionRequest()!=null)p.setAllowEmployeeCorrectionRequest(r.allowEmployeeCorrectionRequest());if(r.correctionRequiresApproval()!=null)p.setCorrectionRequiresApproval(r.correctionRequiresApproval());if(r.correctionReasonRequired()!=null)p.setCorrectionReasonRequired(r.correctionReasonRequired());}
 private void apply(LeavePolicy p,LeavePolicyRequest r){if(r.enabled()!=null)p.setEnabled(r.enabled());if(r.allowEmployeeRequests()!=null)p.setAllowEmployeeRequests(r.allowEmployeeRequests());if(r.requireApproval()!=null)p.setRequireApproval(r.requireApproval());if(r.reasonRequired()!=null)p.setReasonRequired(r.reasonRequired());if(r.attachmentRequired()!=null)p.setAttachmentRequired(r.attachmentRequired());if(r.minimumNoticeDays()!=null)p.setMinimumNoticeDays(r.minimumNoticeDays());if(r.allowHalfDayLeave()!=null)p.setAllowHalfDayLeave(r.allowHalfDayLeave());if(r.allowHourlyLeave()!=null)p.setAllowHourlyLeave(r.allowHourlyLeave());if(r.allowNegativeBalance()!=null)p.setAllowNegativeBalance(r.allowNegativeBalance());if(r.carryOverEnabled()!=null)p.setCarryOverEnabled(r.carryOverEnabled());if(r.carryOverMaximumDays()!=null)p.setCarryOverMaximumDays(r.carryOverMaximumDays());}
 private void apply(PayrollPolicy p,PayrollPolicyRequest r){if(r.enabled()!=null)p.setEnabled(r.enabled());if(r.payrollFrequency()!=null)p.setPayrollFrequency(r.payrollFrequency());if(r.payDateRule()!=null)p.setPayDateRule(r.payDateRule());if(r.payrollApprovalRequired()!=null)p.setPayrollApprovalRequired(r.payrollApprovalRequired());if(r.overtimeAuthorizationRequired()!=null)p.setOvertimeAuthorizationRequired(r.overtimeAuthorizationRequired());if(r.overtimeCalculationMethod()!=null)p.setOvertimeCalculationMethod(r.overtimeCalculationMethod());if(r.weekdayOvertimeMultiplier()!=null)p.setWeekdayOvertimeMultiplier(r.weekdayOvertimeMultiplier());if(r.weekendOvertimeMultiplier()!=null)p.setWeekendOvertimeMultiplier(r.weekendOvertimeMultiplier());if(r.holidayOvertimeMultiplier()!=null)p.setHolidayOvertimeMultiplier(r.holidayOvertimeMultiplier());if(r.lateDeductionEnabled()!=null)p.setLateDeductionEnabled(r.lateDeductionEnabled());if(r.absenceDeductionEnabled()!=null)p.setAbsenceDeductionEnabled(r.absenceDeductionEnabled());if(r.unpaidLeaveDeductionEnabled()!=null)p.setUnpaidLeaveDeductionEnabled(r.unpaidLeaveDeductionEnabled());if(r.missingAttendanceHandling()!=null)p.setMissingAttendanceHandling(r.missingAttendanceHandling());if(r.payrollCutoffDay()!=null)p.setPayrollCutoffDay(r.payrollCutoffDay());}
 private AttendancePolicyResponse out(AttendancePolicy p){return new AttendancePolicyResponse(p.getEffectiveFrom(),p.isEnabled(),p.isRequireCheckIn(),p.isRequireCheckOut(),p.getCheckInMethod(),p.getGracePeriodMinutes(),p.isAllowEarlyCheckIn(),p.getCheckOutMethod(),p.isAllowEarlyCheckout(),p.isEarlyCheckoutRequiresApproval(),p.isRequireAttendanceQr(),p.isRequireLocation(),p.isAllowRemoteAttendance(),p.getMissingCheckoutHandling(),p.isAllowEmployeeCorrectionRequest(),p.isCorrectionRequiresApproval(),p.isCorrectionReasonRequired());}
 private LeavePolicyResponse out(LeavePolicy p){return new LeavePolicyResponse(p.getEffectiveFrom(),p.isEnabled(),p.isAllowEmployeeRequests(),p.isRequireApproval(),p.isReasonRequired(),p.isAttachmentRequired(),p.getMinimumNoticeDays(),p.isAllowHalfDayLeave(),p.isAllowHourlyLeave(),p.isAllowNegativeBalance(),p.isCarryOverEnabled(),p.getCarryOverMaximumDays());}
 private PayrollPolicyResponse out(PayrollPolicy p){return new PayrollPolicyResponse(p.getEffectiveFrom(),p.isEnabled(),p.getPayrollFrequency(),p.getPayDateRule(),p.isPayrollApprovalRequired(),p.isOvertimeAuthorizationRequired(),p.getOvertimeCalculationMethod(),p.getWeekdayOvertimeMultiplier(),p.getWeekendOvertimeMultiplier(),p.getHolidayOvertimeMultiplier(),p.isLateDeductionEnabled(),p.isAbsenceDeductionEnabled(),p.isUnpaidLeaveDeductionEnabled(),p.getMissingAttendanceHandling(),p.getPayrollCutoffDay());}
}
